#include <algorithm>
#include <map>
#include <string>
#include <utility>
#include <vector>

class Inventory
{
public:
    Inventory(std::size_t slots, std::map<std::string, int> stackLimits)
        : m_slots(slots), m_limits{ std::move(stackLimits) } {}

    int add(const std::string& id, int count)
    {
        const auto limit{ m_limits.find(id) };
        if (limit == m_limits.end() || count <= 0) return count > 0 ? count : 0;
        for (auto& [slotId, n] : m_slots)                 // top up matching stacks first
        {
            if (count == 0) break;
            if (slotId != id) continue;
            const int room{ limit->second - n };
            const int moved{ std::min(room, count) };
            n += moved; count -= moved;
        }
        for (auto& [slotId, n] : m_slots)                 // then empty slots
        {
            if (count == 0) break;
            if (n != 0) continue;
            const int moved{ std::min(limit->second, count) };
            slotId = id; n = moved; count -= moved;
        }
        return count;
    }

    bool remove(const std::string& id, int count)
    {
        if (count <= 0) return true;
        if (this->count(id) < count) return false;
        for (auto it{ m_slots.rbegin() }; it != m_slots.rend() && count > 0; ++it)
        {
            if (it->first != id) continue;
            const int taken{ std::min(it->second, count) };
            it->second -= taken; count -= taken;
            if (it->second == 0) it->first.clear();
        }
        return true;
    }

    int count(const std::string& id) const
    {
        int total{ 0 };
        for (const auto& [slotId, n] : m_slots) if (slotId == id) total += n;
        return total;
    }

    std::pair<std::string, int> slot(std::size_t i) const { return m_slots[i]; }

private:
    std::vector<std::pair<std::string, int>> m_slots;
    std::map<std::string, int> m_limits;
};

