using Slot = std::pair<std::string, int>;
static Inventory bag() { return Inventory{ 4, { { "potion", 5 }, { "dagger", 1 }, { "gold", 999 } } }; }
TEST("the lesson's example")
{
    Inventory inv{ bag() };
    inv.add("potion", 4); inv.add("dagger", 1);
    CHECK_EQ(inv.add("potion", 7), 0);
    CHECK(inv.slot(0) == Slot("potion", 5)); CHECK(inv.slot(1) == Slot("dagger", 1));
    CHECK(inv.slot(2) == Slot("potion", 5)); CHECK(inv.slot(3) == Slot("potion", 1));
    CHECK_EQ(inv.count("potion"), 11);
}
TEST("what does not fit is returned") { Inventory inv{ Inventory{ 1, { { "potion", 5 } } } }; CHECK_EQ(inv.add("potion", 7), 2); CHECK_EQ(inv.count("potion"), 5); }
TEST("unknown items do not fit") { Inventory inv{ bag() }; CHECK_EQ(inv.add("cheese", 3), 3); CHECK_EQ(inv.count("cheese"), 0); }
TEST("unstackable items take a slot each") { Inventory inv{ bag() }; CHECK_EQ(inv.add("dagger", 3), 0); CHECK(inv.slot(2) == Slot("dagger", 1)); CHECK_EQ(inv.add("dagger", 2), 1); }
TEST("remove from the last stack first") { Inventory inv{ bag() }; inv.add("potion", 7); CHECK(inv.remove("potion", 3)); CHECK(inv.slot(0) == Slot("potion", 4)); CHECK(inv.slot(1) == Slot("", 0)); }
TEST("removing too many removes nothing") { Inventory inv{ bag() }; inv.add("potion", 2); CHECK(!inv.remove("potion", 3)); CHECK_EQ(inv.count("potion"), 2); }
TEST("emptied slots are reused") { Inventory inv{ bag() }; inv.add("dagger", 1); inv.remove("dagger", 1); CHECK(inv.slot(0) == Slot("", 0)); inv.add("gold", 50); CHECK(inv.slot(0) == Slot("gold", 50)); }

